hints.tier2Scaffold:
CREATE TABLE assets (
  symbol TEXT,
  company_name TEXT
);

SELECT t.symbol, (t.price - p.avg_cost) * t.quantity as pnl
FROM trades t
JOIN portfolio p ON t.symbol = p.symbol;

SELECT symbol, price,
  RANK() OVER (PARTITION BY symbol ORDER BY price DESC) as price_rank
FROM price_ticks;

SELECT tick_time, price,
  price - LAG(price, 1) OVER (ORDER BY tick_time) as price_change
FROM price_ticks WHERE symbol = 'AAPL';

SELECT symbol FROM assets a
WHERE EXISTS (
  SELECT 1 FROM orders o WHERE o.symbol = a.symbol AND o.status = 'FILLED'
);

SELECT symbol, tick_time, volume,
  SUM(volume) OVER (PARTITION BY symbol ORDER BY tick_time) as cumulative_volume
FROM price_ticks;

WITH trade_stats AS (
  SELECT symbol, SUM(price*quantity) as trade_value FROM trades GROUP BY symbol
),
portfolio_cost AS (
  SELECT symbol, avg_cost*quantity as cost_basis FROM portfolio
)
SELECT t.symbol, t.trade_value, p.cost_basis
FROM trade_stats t
JOIN portfolio_cost p ON t.symbol = p.symbol;
